// Reproduce the pinned official closures without executing the source modules.
import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'
import ts from 'typescript'

const root = process.argv[2]
if (!root) throw Error('Usage: node src/vendor/official-mcpb/recover.mjs OFFICIAL_2_1_283_ROOT [--check]')
const check = process.argv.includes('--check')
const sha = value => crypto.createHash('sha256').update(value).digest('hex')
const records = []
const dir = new URL('./', import.meta.url)
function select(platform, module, names) {
  const manifest = JSON.parse(fs.readFileSync(path.join(root, platform, 'manifest.json'), 'utf8'))
  if (manifest.version !== '2.1.283' || manifest.platform !== platform) throw Error('Unexpected official source')
  const raw = fs.readFileSync(path.join(root, platform, 'raw', module), 'utf8')
  if (sha(raw) !== manifest.modules.find(entry => entry.path === module)?.sha256) throw Error('Source hash mismatch: ' + module)
  const source = ts.createSourceFile(module, raw, ts.ScriptTarget.Latest, true, ts.ScriptKind.JS)
  const nodes = new Set()
  for (const name of names) {
    const node = source.statements.find(statement => statement.name?.text === name ||
      ts.isVariableStatement(statement) && statement.declarationList.declarations.some(d => d.name.getText(source) === name))
    if (!node) throw Error('Missing declaration: ' + name)
    nodes.add(node)
  }
  return [...nodes].map(node => {
    const body = node.getText(source)
    records.push({platform, module, moduleSha256:sha(raw), declaration:node.name?.text ?? node.declarationList.declarations.map(d => d.name.getText(source)).join(','), declarationSha256:sha(body)})
    return body
  }).join('\n')
}
const banner = '// Official npm 2.1.283: unchanged complete declarations; generated by recover.mjs.\n'
const schemaDeclaration = select('darwin-arm64', 'chunk-pwc6cx3d.js', ['m'])
// Only bundler import aliases differ; retain the darwin declaration verbatim.
const linuxSchema = select('linux-x64', 'chunk-sc94k3v4.js', ['m'])
const schemaAliases = {xl:'Pl', XP:'e0', Bl:'jl'}
if (schemaDeclaration !== linuxSchema.replace(/\b(xl|XP|Bl)\b/g, name => schemaAliases[name])) throw Error('Platform schemas differ; review required')
const zodAliases = select('darwin-arm64', 'chunk-2y4x2nqt.js', ['de'])
if (!zodAliases.includes('strictCreate:Pl') || !zodAliases.includes('de=T.create')) throw Error('Zod alias mapping changed')
const linuxZodAliases = select('linux-x64', 'chunk-hn75r78z.js', ['de'])
if (!linuxZodAliases.includes('strictCreate:xl')) throw Error('Linux Zod strict-object alias changed')
for (const [platform,module,zodModule,aliases,strictName] of [
  ['darwin-x64','chunk-ykkz98v2.js','chunk-f0zt8nzn.js',{Hl:'Pl',eP:'e0'},'Hl'],
  ['linux-arm64','chunk-8kdjze1p.js','chunk-8syb0pcn.js',{xl:'Pl',XI:'e0',Hl:'jl'},'xl'],
]) {
  const declaration=select(platform,module,['m'])
  const pattern=new RegExp(`\\b(${Object.keys(aliases).join('|')})\\b`,'g')
  if(schemaDeclaration!==declaration.replace(pattern,name=>aliases[name])) throw Error('Architecture schema differs: '+platform)
  if(!select(platform,zodModule,['de']).includes('strictCreate:'+strictName)) throw Error('Architecture Zod alias changed')
}
const outputs = {
  'zip.js': banner + 'import {inflateRawSync as Ue} from "node:zlib";\n' +
    select('darwin-arm64', 'chunk-63ryp0ar.js', ['P']) + '\n' +
    select('darwin-arm64', 'chunk-m9e6tp58.js', ['Be', 'R', 'I', 'A', 'de', 'qe', 'Ye']) + '\nexport {Ye as unzipValidatedEntries};\n',
  // Pl is ZodObject.strictCreate, NOT the stripping object() constructor.
  'manifest.ts': banner + 'import {z} from "zod/v3";\n' +
    'const de=z.string, fn=z.number, ho=z.boolean, Xn=z.array, Pl=z.strictObject, e0=z.union, gg=z.record, jl=z.enum;\n' +
    schemaDeclaration +
    '\nexport {k as McpbManifestSchema};\nexport type McpbManifest = z.infer<typeof k>;\nexport type McpbUserConfigurationOption = z.infer<typeof v>;\nexport type McpbConfig = z.infer<typeof _>;\n',
}
for (const [platform, module, peerPlatform, peerModule] of [
  ['darwin-arm64','chunk-pwc6cx3d.js','darwin-x64','chunk-ykkz98v2.js'],
  ['linux-x64','chunk-sc94k3v4.js','linux-arm64','chunk-8kdjze1p.js'],
]) {
  const name = platform.split('-')[0]
  const closure=select(platform,module,['z','R','u','j'])
  if(closure!==select(peerPlatform,peerModule,['z','R','u','j'])) throw Error('Architecture config closure differs: '+peerPlatform)
  outputs[`config-${name}.js`] = banner + closure + '\nexport {R as getMcpConfigForManifest};\n'
}
outputs['provenance.json'] = JSON.stringify({version:'2.1.283', records, files:Object.fromEntries(Object.entries(outputs).map(([name,body]) => [name,sha(body)])), adapters:{schema:'zod/v3 aliases; Pl = strictObject verified in chunk-2y4x2nqt.js', config:'Select unchanged darwin/linux closures using process.platform', zip:'Caller validates every entry before inflate; node:zlib only'}}, null, 2) + '\n'
for (const [name, body] of Object.entries(outputs)) {
  const target = new URL(name, dir)
  if (check) { if (fs.readFileSync(target, 'utf8') !== body) throw Error('Generated file differs: ' + name) }
  else fs.writeFileSync(target, body)
}
console.log(`${check ? 'Verified' : 'Generated'} ${Object.keys(outputs).length} official MCPB artifacts`)
